Actionscript.script:
onClipEvent(load){
   垂直速度 = -5;
   起始Y = _parent.Z轴坐标;
   this.onEnterFrame = function()
   {
      _parent._y += 垂直速度;
      垂直速度 += _root.重力加速度;
      if(_parent._y >= 起始Y)
      {
         _parent._y = 起始Y;
         delete this.onEnterFrame;
         _parent.gotoAndPlay("消失");
      }
   };
}
